public class MainActivity extends Activity {
    WebView web; String pendingDamageMetadata=""; String origin=""; File photo; byte[] pendingSave; String lastSavedName; volatile boolean recognizing=false; boolean imageOCR=false; PermissionRequest cameraPermission;
    final int DAMAGE=105,EXPORT_PHOTO=107;
    final int CAMERA=101,SAVE=102,PICK=103; ValueCallback<Uri[]> fileChooser;
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE);origin=getPreferences(0).getString("server","");if(state!=null){String p=state.getString("photo");if(p!=null)photo=new File(p);}if(origin.isEmpty())setup();else launch();}
    @Override protected void onResume(){super.onResume();String id=getPreferences(0).getString("damage_pending","");if(!id.isEmpty()){try{if(PhotoQueue.file(this,id,".original").length()>0)finishDamage(true);}catch(Exception ignored){}}try{JSONObject a=PhotoQueue.session(this);PhotoQueue.resume(this,a.optString("origin"),a.optString("owner"));}catch(Exception ignored){}}
    @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(photo!=null)out.putString("photo",photo.getAbsolutePath());}
    void setup(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(40,100,40,40);TextView title=new TextView(this);title.setText("스쿠터 창고\n서버 연결");title.setTextSize(28);l.addView(title);TextView guide=new TextView(this);guide.setText("PC와 같은 HTTPS 서버 주소를 입력하세요.\n예: https://warehouse.example.com\n자체 서버를 먼저 설치해야 합니다.");guide.setPadding(0,30,0,30);l.addView(guide);EditText url=new EditText(this);url.setSingleLine();url.setHint("https://서버주소");url.setText(origin);l.addView(url);Button connect=new Button(this);connect.setText("연결");l.addView(connect);connect.setOnClickListener(v->{try{Uri u=Uri.parse(url.getText().toString().trim());if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null)throw new Exception();origin="https://"+u.getAuthority();getPreferences(0).edit().putString("server",origin).apply();launch();}catch(Exception e){Toast.makeText(this,"올바른 HTTPS 서버 주소를 입력하세요.",1).show();}});setContentView(l);}
    boolean trusted(String url){try{Uri u=Uri.parse(url),o=Uri.parse(origin);return "https".equals(u.getScheme())&&Objects.equals(u.getHost(),o.getHost())&&u.getPort()==o.getPort();}catch(Exception e){return false;}}
    void launch(){web=new WebView(this);web.setBackgroundColor(Color.rgb(244,247,248));web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(true);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.addJavascriptInterface(new Bridge(),"WarehouseNative");web.setWebViewClient(new WebViewClient(){
      @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !trusted(r.getUrl().toString());}
      @Override public void onReceivedSslError(WebView v,android.webkit.SslErrorHandler h,android.net.http.SslError e){h.cancel();Toast.makeText(MainActivity.this,"서버 HTTPS 인증서를 확인하세요.",1).show();}
      @Override public void onPageStarted(WebView v,String url,Bitmap icon){if(!trusted(url)){v.removeJavascriptInterface("WarehouseNative");v.stopLoading();}}
      @Override public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())Toast.makeText(MainActivity.this,"서버 연결 실패. 뒤로 버튼을 길게 눌러 주소를 설정하세요.",1).show();}
    });web.setWebChromeClient(new WebChromeClient(){
      @Override public void onPermissionRequest(PermissionRequest request){runOnUiThread(()->{if(!trusted(request.getOrigin().toString())||!trusted(web.getUrl())){request.deny();return;}boolean video=Arrays.asList(request.getResources()).contains(PermissionRequest.RESOURCE_VIDEO_CAPTURE);if(!video){request.deny();return;}if(checkSelfPermission(android.Manifest.permission.CAMERA)==android.content.pm.PackageManager.PERMISSION_GRANTED)request.grant(new String[]{PermissionRequest.RESOURCE_VIDEO_CAPTURE});else{cameraPermission=request;requestPermissions(new String[]{android.Manifest.permission.CAMERA},104);}});}
      @Override public void onPermissionRequestCanceled(PermissionRequest request){if(cameraPermission==request)cameraPermission=null;}

      @Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){
        if(!trusted(view.getUrl()))return false;
        if(fileChooser!=null)fileChooser.onReceiveValue(null);fileChooser=callback;
        try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,params.getAcceptTypes().length>0?params.getAcceptTypes():new String[]{"*/*"});startActivityForResult(i,PICK);return true;}
        catch(Exception e){fileChooser.onReceiveValue(null);fileChooser=null;return false;}
      }
    });setContentView(web);web.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});web.loadUrl(origin+"/");}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==106){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED&&!pendingDamageMetadata.isEmpty())new Bridge().captureDamage(pendingDamageMetadata);else Toast.makeText(this,"카메라 권한이 필요합니다.",1).show();pendingDamageMetadata="";return;}if(code==104&&cameraPermission!=null){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED&&web!=null&&trusted(web.getUrl()))cameraPermission.grant(new String[]{PermissionRequest.RESOURCE_VIDEO_CAPTURE});else cameraPermission.deny();cameraPermission=null;}}
    class Bridge {
      @JavascriptInterface public void setUploadSession(String token,String owner){runOnUiThread(()->{if(!trusted(web.getUrl()))return;try{PhotoQueue.session(MainActivity.this,origin,owner,token);}catch(Exception e){Toast.makeText(MainActivity.this,"사진 전송 로그인 저장 실패",1).show();}});}
      @JavascriptInterface public void photoJobs(String vehicle,String stay){runOnUiThread(()->{try{if(!trusted(web.getUrl()))return;JSONObject a=PhotoQueue.session(MainActivity.this);JSONArray all=PhotoQueue.list(MainActivity.this,origin,a.optString("owner")),out=new JSONArray();for(int i=0;i<all.length();i++){JSONObject j=all.getJSONObject(i);if(!vehicle.equals(j.optString("vehicle_id"))||!stay.equals(j.optString("stay_id")))continue;File preview=PhotoQueue.file(MainActivity.this,j.getString("id"),".preview.jpg");if(preview.isFile())try(InputStream in=new FileInputStream(preview)){j.put("preview","data:image/jpeg;base64,"+android.util.Base64.encodeToString(PhotoQueue.bytes(in,200000),android.util.Base64.NO_WRAP));}out.put(j);}web.evaluateJavascript("window.onPhotoJobs && window.onPhotoJobs("+out.toString()+")",null);}catch(Exception ignored){}});}
      @JavascriptInterface public void captureDamage(String metadata){runOnUiThread(()->{if(!trusted(web.getUrl()))return;try{
        if(checkSelfPermission(android.Manifest.permission.CAMERA)!=android.content.pm.PackageManager.PERMISSION_GRANTED){pendingDamageMetadata=metadata;requestPermissions(new String[]{android.Manifest.permission.CAMERA},106);return;}JSONObject m=new JSONObject(metadata),a=PhotoQueue.session(MainActivity.this);if(!origin.equals(a.optString("origin")))throw new IOException("먼저 로그인하세요.");
        for(String k:new String[]{"vehicle_id","stay_id"})UUID.fromString(m.getString(k));
        String id=UUID.randomUUID().toString();m.put("id",id);m.put("origin",origin);m.put("owner",a.getString("owner"));m.put("status","capturing");m.put("captured_at",java.time.Instant.now().toString());PhotoQueue.write(MainActivity.this,m);
        getPreferences(0).edit().putString("damage_pending",id).commit();
        Uri uri=FileProvider.getUriForFile(MainActivity.this,getPackageName()+".files",PhotoQueue.file(MainActivity.this,id,".original"));
        Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,uri);i.setClipData(ClipData.newRawUri("original",uri));i.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(i,DAMAGE);
      }catch(Exception e){cancelDamage();Toast.makeText(MainActivity.this,"기본 카메라 실행 실패: "+e.getMessage(),1).show();}});}
      @JavascriptInterface public void exportPhoto(String id){runOnUiThread(()->{try{if(!trusted(web.getUrl()))return;JSONObject j=PhotoQueue.read(MainActivity.this,id),a=PhotoQueue.session(MainActivity.this);if(!j.getString("owner").equals(a.optString("owner"))||!j.getString("origin").equals(origin))return;File f=PhotoQueue.file(MainActivity.this,id,".original");if(!f.exists())throw new IOException("PC에 저장된 원본을 다운로드하세요.");BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getPath(),bounds);String mime=bounds.outMimeType==null?"application/octet-stream":bounds.outMimeType;String ext=mime.contains("jpeg")?"jpg":mime.contains("heif")||mime.contains("heic")?"heic":mime.contains("png")?"png":mime.contains("webp")?"webp":"original";getPreferences(0).edit().putString("export_photo",id).commit();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,j.getString("key")+"_"+id+"."+ext);startActivityForResult(i,EXPORT_PHOTO);}catch(Exception e){Toast.makeText(MainActivity.this,"원본 저장 실패: "+e.getMessage(),1).show();}});}
      @JavascriptInterface public void retryPhoto(String id){runOnUiThread(()->{try{if(!trusted(web.getUrl()))return;JSONObject j=PhotoQueue.read(MainActivity.this,id),a=PhotoQueue.session(MainActivity.this);if(j.getString("owner").equals(a.optString("owner"))&&j.getString("origin").equals(origin)&&!j.optString("status").equals("saved")){PhotoQueue.state(MainActivity.this,id,"pending","");PhotoQueue.enqueue(MainActivity.this,id);}}catch(Exception ignored){}});}
      @JavascriptInterface public void discardPhoto(String id){runOnUiThread(()->{try{if(!trusted(web.getUrl()))return;JSONObject j=PhotoQueue.read(MainActivity.this,id),a=PhotoQueue.session(MainActivity.this);if(!j.getString("owner").equals(a.optString("owner"))||!j.getString("origin").equals(origin))return;new AlertDialog.Builder(MainActivity.this).setMessage("전송 대기 원본을 삭제하면 복구할 수 없습니다. 삭제할까요?").setNegativeButton("취소",null).setPositiveButton("삭제",(d,w)->{androidx.work.WorkManager.getInstance(MainActivity.this).cancelUniqueWork("photo-"+id);PhotoQueue.file(MainActivity.this,id,".original").delete();PhotoQueue.file(MainActivity.this,id,".json").delete();}).show();}catch(Exception ignored){}});}

      @JavascriptInterface public void recognizeImage(String encoded){runOnUiThread(()->{if(!trusted(web.getUrl())||recognizing)return;imageOCR=true;try{if(encoded.length()>16000000)throw new IOException();File dir=new File(getCacheDir(),"vin");dir.mkdirs();photo=new File(dir,"shared-ocr.jpg");try(FileOutputStream out=new FileOutputStream(photo)){out.write(android.util.Base64.decode(encoded,android.util.Base64.DEFAULT));}recognize();}catch(Exception e){callbackError("VIN 사진을 분석할 수 없습니다.");}});}

      @JavascriptInterface public void scan(){runOnUiThread(()->{if(!trusted(web.getUrl()))return;new AlertDialog.Builder(MainActivity.this).setTitle("VIN 촬영").setMessage("17자리 차대번호가 선명하게 보이도록 가까이 촬영하세요. 후면 카메라로 촬영한 뒤 VIN 줄만 영역 선택하세요. 반사광을 피하고 글자를 수평으로 맞추세요. 사진은 서버로 전송하지 않습니다.").setPositiveButton("촬영",(d,w)->camera()).setNegativeButton("취소",null).show();});}
      @JavascriptInterface public void save(String name,String data){runOnUiThread(()->{if(!trusted(web.getUrl()))return;try{if(data.length()>150000000)throw new Exception();pendingSave=android.util.Base64.decode(data,android.util.Base64.DEFAULT);lastSavedName=name.replaceAll("[^a-zA-Z0-9._-]","_");Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(name.endsWith("zip")?"application/zip":name.endsWith("jpg")?"image/jpeg":name.endsWith("png")?"image/png":name.endsWith("webp")?"image/webp":name.endsWith("html")?"text/html":name.endsWith("xlsx")?"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"text/csv");i.putExtra(Intent.EXTRA_TITLE,lastSavedName);startActivityForResult(i,SAVE);}catch(Exception e){Toast.makeText(MainActivity.this,"파일 저장을 시작할 수 없습니다.",1).show();}});}
    }
    void camera(){if(recognizing)return;try{startActivityForResult(new Intent(this,VinCameraActivity.class),CAMERA);}catch(Exception e){callbackError("후면 카메라를 실행할 수 없습니다. VIN을 직접 입력하세요.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==EXPORT_PHOTO){String id=getPreferences(0).getString("export_photo","");getPreferences(0).edit().remove("export_photo").commit();if(result==RESULT_OK&&data!=null&&!id.isEmpty())try(InputStream in=new FileInputStream(PhotoQueue.file(this,id,".original"));OutputStream out=getContentResolver().openOutputStream(data.getData())){byte[] b=new byte[65536];int n;while((n=in.read(b))>0)out.write(b,0,n);Toast.makeText(this,"원본 사본 저장 완료",0).show();}catch(Exception e){Toast.makeText(this,"원본 사본 저장 실패. 앱 원본은 보존됩니다.",1).show();}return;}if(request==DAMAGE){finishDamage(result==RESULT_OK);return;}if(request==PICK){if(fileChooser!=null){fileChooser.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);fileChooser=null;}return;}if(request==SAVE){if(result==RESULT_OK&&data!=null&&pendingSave!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(pendingSave);Toast.makeText(this,"파일 저장 완료",0).show();}catch(Exception e){Toast.makeText(this,"파일 저장 실패",1).show();}}pendingSave=null;return;}if(request!=CAMERA)return;if(result!=RESULT_OK){return;}String path=data==null?null:data.getStringExtra("photo");try{photo=path==null?null:new File(path);if(photo==null||!photo.getCanonicalPath().startsWith(new File(getCacheDir(),"vin").getCanonicalPath()+File.separator))throw new IOException();recognize();}catch(Exception e){callbackError("촬영한 사진을 찾지 못했습니다. 다시 촬영하세요.");}}
    void cancelDamage(){String id=getPreferences(0).getString("damage_pending","");if(!id.isEmpty()){PhotoQueue.file(this,id,".original").delete();PhotoQueue.file(this,id,".json").delete();}getPreferences(0).edit().remove("damage_pending").commit();}
    void finishDamage(boolean success){String id=getPreferences(0).getString("damage_pending","");if(id.isEmpty())return;try{revokeUriPermission(FileProvider.getUriForFile(this,getPackageName()+".files",PhotoQueue.file(this,id,".original")),Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}if(!success){cancelDamage();return;}try{
      File original=PhotoQueue.file(this,id,".original");if(!original.isFile()||original.length()==0)throw new IOException("촬영 원본 없음");
      JSONObject j=PhotoQueue.read(this,id);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(original.getPath(),o);BitmapFactory.Options small=new BitmapFactory.Options();int sample=1;while(Math.max(o.outWidth,o.outHeight)/sample>320)sample*=2;small.inSampleSize=sample;Bitmap bitmap=BitmapFactory.decodeFile(original.getPath(),small);if(bitmap!=null){Matrix m=new Matrix();int orientation=new ExifInterface(original).getAttributeInt(ExifInterface.TAG_ORIENTATION,1);if(orientation==3)m.postRotate(180);if(orientation==6)m.postRotate(90);if(orientation==8)m.postRotate(270);if(orientation==2)m.postScale(-1,1);if(orientation==4){m.postRotate(180);m.postScale(-1,1);}if(orientation==5){m.postRotate(90);m.postScale(-1,1);}if(orientation==7){m.postRotate(270);m.postScale(-1,1);}Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),m,true);try(FileOutputStream out=new FileOutputStream(PhotoQueue.file(this,id,".preview.jpg"))){rotated.compress(Bitmap.CompressFormat.JPEG,80,out);}if(rotated!=bitmap)rotated.recycle();bitmap.recycle();}j.put("width",o.outWidth);j.put("height",o.outHeight);j.put("size",original.length());j.put("status","pending");PhotoQueue.write(this,j);getPreferences(0).edit().remove("damage_pending").commit();PhotoQueue.enqueue(this,id);
      if(web!=null&&trusted(web.getUrl()))web.evaluateJavascript("window.dispatchEvent(new Event('warehouse-photo-captured'))",null);
    }catch(Exception e){try{PhotoQueue.state(this,id,"failed",e.getMessage());}catch(Exception ignored){}Toast.makeText(this,"사진을 보관했습니다. 전송 상태를 확인하세요.",1).show();}}
    void recognize(){if(recognizing)return;recognizing=true;Toast.makeText(this,"선택한 VIN 영역을 분석 중입니다…",0).show();new Thread(()->{try{
      BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(photo.getPath(),bounds);BitmapFactory.Options options=new BitmapFactory.Options();int sample=1;while(Math.max(bounds.outWidth,bounds.outHeight)/sample>4096)sample*=2;options.inSampleSize=sample;Bitmap bmp=BitmapFactory.decodeFile(photo.getPath(),options);if(bmp==null)throw new IOException();final Bitmap original=bmp;
      final Bitmap processed=Bitmap.createBitmap(bmp.getWidth(),bmp.getHeight(),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(processed);Paint paint=new Paint();ColorMatrix gray=new ColorMatrix();gray.setSaturation(0);ColorMatrix contrast=new ColorMatrix(new float[]{1.35f,0,0,0,-30,0,1.35f,0,0,-30,0,0,1.35f,0,-30,0,0,0,1,0});gray.postConcat(contrast);paint.setColorFilter(new ColorMatrixColorFilter(gray));canvas.drawBitmap(bmp,0,0,paint);
      var recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);
      recognizer.process(InputImage.fromBitmap(original,0)).continueWithTask(first->{String raw=first.isSuccessful()?first.getResult().getText():"";return recognizer.process(InputImage.fromBitmap(processed,0)).continueWith(second->{if(!first.isSuccessful()&&!second.isSuccessful())throw new IOException("OCR failed");return raw+"\n"+(second.isSuccessful()?second.getResult().getText():"");});}).addOnSuccessListener(raw->{try{JSONObject obj=new JSONObject();obj.put("raw",raw);obj.put("candidates",new JSONArray(VinCandidates.extract(raw)));int w=Math.min(original.getWidth(),1400),h=Math.max(1,original.getHeight()*w/original.getWidth());Bitmap preview=Bitmap.createScaledBitmap(original,w,h,true);ByteArrayOutputStream buf=new ByteArrayOutputStream();preview.compress(Bitmap.CompressFormat.JPEG,85,buf);obj.put("preview",android.util.Base64.encodeToString(buf.toByteArray(),android.util.Base64.NO_WRAP));if(preview!=original)preview.recycle();callback(obj);}catch(Exception e){callbackError("인식 결과를 처리하지 못했습니다. 다시 촬영하세요.");}}).addOnFailureListener(e->callbackError("VIN 인식 실패. 글자가 선명하도록 다시 촬영하세요.")).addOnCompleteListener(t->{recognizer.close();original.recycle();processed.recycle();if(photo!=null)photo.delete();recognizing=false;});
    }catch(Exception e){if(photo!=null)photo.delete();recognizing=false;callbackError("사진을 읽지 못했습니다. 다시 촬영하세요.");}},"vin-preprocess").start();}
    void callback(JSONObject obj){runOnUiThread(()->{if(web!=null&&trusted(web.getUrl()))web.evaluateJavascript((imageOCR?"window.onWarehouseOCR && window.onWarehouseOCR(":"window.onNativeVin && window.onNativeVin(")+obj.toString()+")",null);imageOCR=false;});}
    void callbackError(String message){try{JSONObject o=new JSONObject();o.put("error",message);callback(o);}catch(Exception ignored){}}
    @Override public boolean onKeyLongPress(int key,android.view.KeyEvent event){if(key==KeyEvent.KEYCODE_BACK){onBackPressed();return true;}return super.onKeyLongPress(key,event);}
    void exitMenu(){new AlertDialog.Builder(this).setItems(new String[]{"서버 주소 변경","앱 닫기","취소"},(d,w)->{if(w==0){web.removeJavascriptInterface("WarehouseNative");web.destroy();web=null;setup();}if(w==1)finish();}).show();}
    @Override public void onBackPressed(){if(recognizing){Toast.makeText(this,"VIN 인식 중입니다. 잠시 기다려 주세요.",0).show();return;}if(web!=null&&trusted(web.getUrl()))web.evaluateJavascript("!!(window.handleWarehouseBack && window.handleWarehouseBack())",result->{if(!"true".equals(result))exitMenu();});else if(web!=null)exitMenu();else super.onBackPressed();}
}
